 for(const w of s.capture_windows)fail(w.closes_at>=w.opens_at&&['PLAN','REPORT'].includes(w.kind),'Ventana de captura inválida.');
 for(const a of s.teaching_assignments)fail(a.weekly_minutes>0&&Number.isInteger(a.students)&&a.students>=0,'Horas o alumnos inválidos.');
 for(const r of s.course_results)fail(r.enrolled>=0&&r.passed>=0&&r.passed<=r.enrolled,'Resultado de curso inválido.');
